<script setup lang="ts">import {ref,computed,watch} from 'vue';import type {Workspace} from '../stores/workspace';import {create} from '../api/studies';import * as runs from '../api/runs';import {useAction} from '../hooks/useAction';import Heading from '../components/common/Heading.vue';import Notice from '../components/common/Notice.vue';import Empty from '../components/common/Empty.vue';import PolicyStrip from '../components/PolicyStrip.vue';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const emit=defineEmits<{open:[string]}>();const name=ref('足迹五组·新包络研究'),sid=ref('demo-survey'),pid=ref('demo-policy'),groups=ref<string[]>([]);const survey=computed(()=>props.data.surveys.find(s=>s.id===sid.value)||props.data.surveys[0]);watch(()=>survey.value?.id,()=>groups.value=survey.value?.groups.map(g=>g.group_id)||[],{immediate:true});const{busy,error,notice,act}=useAction();</script><template><Heading index="04 / FROZEN STUDIES" title="选择点组，冻结完整来源。" detail="选择仅决定本次计算范围；快照仍锁定完整原始测组、去重规则与方向参数，不因切换组删除源数据。"/><section v-if="canWrite" class="form-section"><form class="form-grid" @submit.prevent="act(async()=>{await create({name,survey_id:survey!.id,policy_id:pid,group_ids:groups});await refresh()},'研究快照已冻结，可提交后台包络比较')"><label>包络研究名称<input aria-label="包络研究名称" required v-model="name"/></label><label>研究测组<select aria-label="研究测组" v-model="sid"><option v-for="s in data.surveys" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>研究边界口径<select aria-label="研究边界口径" v-model="pid"><option v-for="p in data.policies" :key="p.id" :value="p.id">{{p.name}}</option></select></label><div class="group-checks"><span>本次计算点组</span><label v-for="g in survey?.groups" :key="g.group_id"><input type="checkbox" :aria-label="'选择'+g.group_id" :value="g.group_id" v-model="groups"/>{{g.group_id}} {{g.name}}</label></div><button class="primary" :disabled="busy">冻结包络研究</button></form><Notice :error="error" :notice="notice"/></section><Empty v-if="!data.studies.length">先导入local_m测组、保存去重规则，再选择至少一个点组冻结研究。</Empty><article v-for="s in data.studies" :key="s.id" class="scenario-row"><div><p class="eyebrow">SNAPSHOT / 源{{s.snapshot.survey.groups.length}}组 / 本次{{s.group_ids.join(', ')}}</p><h2>{{s.name}}</h2><p>{{s.snapshot.survey.source}}</p><PolicyStrip :policy="s.snapshot.policy"/></div><div><button v-if="canWrite" :disabled="busy" @click="act(async()=>{const r=await runs.create({study_id:s.id});await refresh();emit('open',r.id)},'包络比较已提交Redis')">运行凸包与定向框 →</button><small>{{data.runs.filter(r=>r.study_id===s.id).length}}次独立运行</small></div></article></template>